## 3. Adding playback control with the **SoundCloud Widget API**

If you need more than just a static player (e.g., custom play/pause buttons, track‑list navigation, volume sliders), you can talk to the iframe via the Widget API.

### Step‑by‑step

1. **Load the widget script** (only once per page)

   ```html
   <script src="https://w.soundcloud.com/player/api.js" type="text/javascript"></script>
   ```

2. **Create the iframe** (as shown above) and give it an `id`:

   ```html
   <iframe id="sc-widget"
           src="https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/123456789&color=%23ff5500"
           width="100%" height="166" scrolling="no" frameborder="no"></iframe>
   ```

3. **Instantiate the widget and bind events**

   ```js
   // Wait for the iframe to load
   const iframeElement = document.getElementById('sc-widget');
   const widget = SC.Widget(iframeElement);

   // Example: custom play/pause button
   const playBtn = document.getElementById('play');
   const pauseBtn = document.getElementById('pause');

   playBtn.addEventListener('click', () => widget.play());
   pauseBtn.addEventListener('click', () => widget.pause());

   // Example: show current time / duration
   widget.bind(SC.Widget.Events.PLAY_PROGRESS, function (e) {
     const current = Math.floor(e.currentPosition / 1000);
     const total   = Math.floor(e.duration / 1000);
     document.getElementById('time').textContent = `${current}s / ${total}s`;
   });

   // Example: load a new track programmatically
   function loadTrack(trackId) {
     const url = `https://api.soundcloud.com/tracks/${trackId}`;
     widget.load(url, {
       auto_play: true,
       show_artwork: true
     });
   }
